import { _decorator, Component, MeshRenderer } from 'cc';
import { BuffId, CFG, COLORS, HazardType, advanceZ, laneX, makeBox, makeCylinder, makePlane, unlitMaterial } from './GameConfig';
import { IUnit, IHazard, removeFrom, world } from './World';
import { bus, EV } from './EventBus';
import { BuffSystem } from './BuffSystem';

const { ccclass } = _decorator;

/** 油桶：可击毁，掉落临时增益（攻速 / 伤害 / 僚机 / 回血） */
@ccclass('Barrel')
export class Barrel extends Component implements IUnit {
    laneIndex = 1;
    alive = false;
    private hp = 0;
    private buffs: BuffSystem = null!;

    init(buffs: BuffSystem): void {
        this.buffs = buffs;
    }

    build(lane: number, z: number): void {
        this.laneIndex = lane;
        this.hp = 12;
        this.alive = true;
        this.node.removeAllChildren();
        this.node.setPosition(laneX(lane), 0, z);
        const body = makeCylinder('Barrel', 0.5, 1.2, COLORS.barrel, this.node);
        body.setPosition(0, 0.6, 0);
    }

    takeDamage(dmg: number): void {
        if (!this.alive) return;
        this.hp -= dmg;
        if (this.hp <= 0) this.grant();
    }

    /** 撞破也给 buff：风险收益设计的一部分 */
    private grant(): void {
        this.alive = false;
        const pick = Math.random();
        if (pick < 0.35) {
            this.buffs.apply(BuffId.Damage, 0.4, 10, '伤害+40%');
        } else if (pick < 0.7) {
            this.buffs.apply(BuffId.FireRate, 0.3, 10, '攻速+30%');
        } else {
            this.buffs.apply(BuffId.Escort, 1, 10, '僚机支援');
        }
        removeFrom(world.objects, this);
        world.release('barrel', this.node);
    }

    update(dt: number): void {
        if (!this.alive) return;
        advanceZ(this.node, world.travelSpeed * dt);
        if (Math.abs(this.node.position.z - world.playerZ) < 1.4 && world.playerLane === this.laneIndex) {
            this.grant();
            return;
        }
        if (this.node.position.z > CFG.despawnZ) {
            this.alive = false;
            removeFrom(world.objects, this);
            world.release('barrel', this.node);
        }
    }
}

/** 不可破坏危险体：打不掉，碰到直接扣大量血（Rule.md 最高优先级） */
@ccclass('Hazard')
export class Hazard extends Component implements IHazard {
    laneIndex = 1;
    alive = false;
    kind: HazardType = HazardType.Spike;
    private touched = false;

    build(kind: HazardType, lane: number, z: number): void {
        this.kind = kind;
        this.laneIndex = lane;
        this.alive = true;
        this.touched = false;
        this.node.removeAllChildren();
        this.node.setPosition(laneX(lane), 0, z);

        if (kind === HazardType.Roller) {
            const r = makeCylinder('Roller', 1.0, CFG.laneWidth * 0.9, COLORS.hazard, this.node);
            r.setPosition(0, 1.0, 0);
            r.setRotationFromEuler(0, 0, 90);
            const core = makeBox('Core', 1.6, 1.2, 1.6, COLORS.wall, this.node);
            core.setPosition(0, 1.2, 0);
        } else if (kind === HazardType.Spike) {
            for (let i = -1; i <= 1; i++) {
                const s = makeBox('Spike', 0.5, 1.4, 0.5, COLORS.hazard, this.node);
                s.setPosition(i * 1.0, 0.7, 0);
                s.setRotationFromEuler(0, 0, 18 * i);
            }
            const base = makeBox('Base', 3.0, 0.3, 1.6, COLORS.wall, this.node);
            base.setPosition(0, 0.15, 0);
        } else {
            const c = makeBox('Charger', 1.1, 1.4, 1.1, COLORS.hazard, this.node);
            c.setPosition(0, 0.7, 0);
            const f = makeBox('Flag', 0.2, 1.6, 0.2, COLORS.bulletHead, this.node);
            f.setPosition(0, 2.2, 0);
        }
    }

    update(dt: number): void {
        if (!this.alive) return;
        // 冲撞怪跑得比世界推进更快
        const sp = world.travelSpeed + (this.kind === HazardType.Charger ? 6 : 0);
        advanceZ(this.node, sp * dt);
        if (this.kind === HazardType.Roller) {
            const r = this.node.children[0];
            if (r) r.setRotationFromEuler(0, 0, 90 + this.node.position.z * 60);
        }
        if (!this.touched && Math.abs(this.node.position.z - world.playerZ) < 1.5 && world.playerLane === this.laneIndex) {
            this.touched = true;
            world.hitPlayer(CFG.hazardDamage);
        }
        if (this.node.position.z > CFG.despawnZ) {
            this.alive = false;
            removeFrom(world.hazards, this);
            world.release('hazard', this.node);
        }
    }
}

/** 数字门：有血量条，打空后大额奖励（技能满充 + 本局永久增伤） */
@ccclass('NumberGate')
export class NumberGate extends Component implements IUnit {
    laneIndex = 0;
    alive = false;
    hp = 0;
    maxHp = 130;
    private buffs: BuffSystem = null!;
    private touched = false;

    init(buffs: BuffSystem): void {
        this.buffs = buffs;
    }

    /** 覆盖左侧两条车道，右侧留一条规避路线：打或绕，由玩家取舍 */
    build(z: number): void {
        this.laneIndex = 0;
        this.hp = this.maxHp;
        this.alive = true;
        this.touched = false;
        this.node.removeAllChildren();
        this.node.setPosition(laneX(0) + CFG.laneWidth / 2, 0, z);
        for (const d of [-1, 1]) {
            const post = makeBox('Post', 0.4, 3.2, 0.4, COLORS.gate, this.node);
            post.setPosition(d * CFG.laneWidth, 1.6, 0);
        }
        const bar = makeBox('Bar', CFG.laneWidth * 2, 0.4, 0.4, COLORS.gate, this.node);
        bar.setPosition(0, 3.2, 0);
        const panel = makeBox('Panel', CFG.laneWidth * 2, 2.6, 0.12, COLORS.gate, this.node);
        panel.setPosition(0, 1.6, 0);
    }

    takeDamage(dmg: number): void {
        if (!this.alive) return;
        this.hp -= dmg;
        bus.emit(EV.GATE_PROMPT, `数字门 ${Math.max(0, Math.ceil(this.hp))}/${this.maxHp}　打爆可得技能满充 + 增伤 20%`);
        if (this.hp <= 0) {
            this.alive = false;
            this.buffs.applyPermanent(BuffId.Damage, 0.2, '增伤+20%');
            world.chargeSkill(CFG.skillMax);
            bus.emit(EV.GATE_DONE, '数字门已击破：技能满充 + 增伤 20%');
            removeFrom(world.objects, this);
            world.release('gate', this.node);
        }
    }

    update(dt: number): void {
        if (!this.alive) return;
        advanceZ(this.node, world.travelSpeed * dt);
        // 门被绕过后提示消失
        if (this.node.position.z > world.playerZ + 2) {
            bus.emit(EV.GATE_PROMPT, '');
        }
        // 门板横跨左两条车道：硬闯也要付代价，逼玩家在「打爆」和「绕开」间二选一
        if (!this.touched && Math.abs(this.node.position.z - world.playerZ) < 1.2 && world.playerLane <= 1) {
            this.touched = true;
            world.hitPlayer(CFG.hazardDamage * 0.6);
        }
        if (this.node.position.z > CFG.despawnZ) {
            this.alive = false;
            removeFrom(world.objects, this);
            world.release('gate', this.node);
        }
    }
}

/** 局内增益门（Roguelike 二选一）：从哪条车道穿过就拿哪个 buff */
@ccclass('BuffGate')
export class BuffGate extends Component {
    laneIndex = 0;
    alive = false;
    resolved = false;
    buffId: BuffId = BuffId.Damage;
    buffValue = 0.3;
    label = '';

    build(lane: number, z: number, id: BuffId, value: number, label: string): void {
        this.laneIndex = lane;
        this.alive = true;
        this.resolved = false;
        this.buffId = id;
        this.buffValue = value;
        this.label = label;
        this.node.removeAllChildren();
        this.node.setPosition(laneX(lane), 0, z);
        for (const d of [-1, 1]) {
            const post = makeBox('Post', 0.3, 3.0, 0.3, COLORS.buffGate, this.node);
            post.setPosition(d * CFG.laneWidth * 0.45, 1.5, 0);
        }
        const top = makeBox('Top', CFG.laneWidth * 0.95, 0.3, 0.3, COLORS.buffGate, this.node);
        top.setPosition(0, 3.0, 0);
        const glow = makePlane('Glow', CFG.laneWidth * 0.85, 1.6, COLORS.buffGate, this.node);
        glow.setPosition(0, 0.05, 0);
    }

    update(dt: number): void {
        if (!this.alive) return;
        advanceZ(this.node, world.travelSpeed * dt);
        // 没被选中也要回收，否则会一直挂在场景里
        if (this.node.position.z > CFG.despawnZ) this.release();
    }

    release(): void {
        this.alive = false;
        world.release('buffGate', this.node);
    }
}

/** 终点 XP 箱子：本局最核心产出物（英雄经验） */
@ccclass('GoalBox')
export class GoalBox extends Component {
    alive = false;
    private spin = 0;

    build(z: number): void {
        this.alive = true;
        this.spin = 0;
        this.node.removeAllChildren();
        this.node.setPosition(0, 0, z);
        const box = makeBox('XPBox', 2.0, 2.0, 2.0, COLORS.goal, this.node);
        box.setPosition(0, 1.4, 0);
        const ring = makePlane('Ring', 3.2, 3.2, COLORS.bulletHead, this.node);
        ring.setPosition(0, 0.06, 0);
    }

    update(dt: number): void {
        if (!this.alive) return;
        this.spin += dt * 120;
        const box = this.node.children[0];
        if (box) box.setRotationFromEuler(0, this.spin, 0);
        advanceZ(this.node, world.travelSpeed * dt);
        if (this.node.position.z >= world.playerZ - 1.0) {
            this.alive = false;
            world.onGoal();
            world.release('goal', this.node);
        }
    }
}

/** BOSS 多轨道 AOE 的预警条（纯视觉，伤害由 BOSS 结算） */
@ccclass('WarningStripe')
export class WarningStripe extends Component {
    private life = 0;
    private toggle = 0;
    private on = false;

    build(lane: number, seconds: number): void {
        this.life = seconds;
        this.toggle = 0;
        this.on = false;
        this.node.setPosition(laneX(lane), 0.08, world.playerZ - 8);
        // 覆盖玩家前方的整条车道
        const mr = this.node.getComponent(MeshRenderer);
        if (mr) mr.setMaterial(unlitMaterial(COLORS.hazard), 0);
    }

    update(dt: number): void {
        this.life -= dt;
        this.toggle -= dt;
        if (this.toggle <= 0) {
            this.toggle = 0.14;
            this.on = !this.on;
            const mr = this.node.getComponent(MeshRenderer);
            if (mr) mr.setMaterial(unlitMaterial(this.on ? COLORS.hazard : COLORS.wall), 0);
        }
        if (this.life <= 0) {
            world.release('warning', this.node);
        }
    }
}
